    def fail(exc=None):
        error = FloatingPointError(
            "non-finite value encountered during Davies-Bouldin score"
        )
        if exc is None:
            raise error
        raise error from exc

    def euclidean(a, b):
        """``sqrt(math.fsum((a_j - b_j) ** 2))`` in column order, with
        post-validation failures raising FloatingPointError."""
